using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using System.Text;
using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using EduSphere.Web.Authorization;
using EduSphere.Web.Security;
using EduSphere.Web.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Pages.Enterprise;
[Authorize(Policy=AuthorizationPolicies.FinanceManager)]
public sealed class AccountingModel(TenantDbContext db,IBranchAccessService branchAccess,IFinanceAccountingService finance):PageModel
{
 public IReadOnlyList<Branch> Branches{get;private set;}=[];public IReadOnlyList<ChartOfAccount> Accounts{get;private set;}=[];public IReadOnlyList<AccountingPeriod> Periods{get;private set;}=[];public IReadOnlyList<JournalEntry> Journals{get;private set;}=[];public IReadOnlyList<BankAccount> Banks{get;private set;}=[];public IReadOnlyList<BankStatementLine> BankLines{get;private set;}=[];public IReadOnlyList<TaxCode> Taxes{get;private set;}=[];public IReadOnlyList<FeeStructure> Structures{get;private set;}=[];public IReadOnlyList<FeeInstallmentPlan> Plans{get;private set;}=[];public IReadOnlyList<LateFeeRule> LateRules{get;private set;}=[];public IReadOnlyList<ConcessionRule> ConcessionRules{get;private set;}=[];public IReadOnlyList<BalanceRow> TrialBalance{get;private set;}=[];
 [BindProperty]public AccountInput Account{get;set;}=new();[BindProperty]public VoucherInput Voucher{get;set;}=new();[BindProperty]public PeriodInput Period{get;set;}=new();[BindProperty]public BankInput Bank{get;set;}=new();[BindProperty]public BankLineInput Statement{get;set;}=new();[BindProperty]public TaxInput Tax{get;set;}=new();[BindProperty]public PlanInput Plan{get;set;}=new();[BindProperty]public LateInput Late{get;set;}=new();[BindProperty]public ConcessionRuleInput Concession{get;set;}=new();[TempData]public string? Feedback{get;set;}
 public sealed class AccountInput{public Guid? BranchId{get;set;}[Required,StringLength(30)]public string Code{get;set;}="";[Required,StringLength(150)]public string Name{get;set;}="";public AccountType Type{get;set;}}
 public sealed class VoucherInput{public Guid? BranchId{get;set;}[Required]public Guid? DebitAccountId{get;set;}[Required]public Guid? CreditAccountId{get;set;}[Range(.01,100000000)]public decimal Amount{get;set;}public DateOnly PostingDate{get;set;}=DateOnly.FromDateTime(DateTime.UtcNow);public VoucherType Type{get;set;}=VoucherType.Journal;[Required,StringLength(250)]public string Narration{get;set;}="";}
 public sealed class PeriodInput{public Guid? BranchId{get;set;}[Required]public string Name{get;set;}="";public DateOnly StartsOn{get;set;}=new(DateTime.UtcNow.Year,4,1);public DateOnly EndsOn{get;set;}=new(DateTime.UtcNow.Year+1,3,31);}
 public sealed class BankInput{[Required]public Guid? BranchId{get;set;}[Required]public Guid? ChartOfAccountId{get;set;}[Required]public string BankName{get;set;}="";[Required]public string AccountNumberMasked{get;set;}="";public string? IfscCode{get;set;}}
 public sealed class BankLineInput{[Required]public Guid? BankAccountId{get;set;}public DateOnly TransactionDate{get;set;}=DateOnly.FromDateTime(DateTime.UtcNow);[Required]public string Description{get;set;}="";public string? Reference{get;set;}public decimal Debit{get;set;}public decimal Credit{get;set;}}
 public sealed class TaxInput{[Required]public string Code{get;set;}="GST18";[Required]public string Name{get;set;}="GST 18%";public TaxType Type{get;set;}=TaxType.Gst;[Range(0,100)]public decimal Rate{get;set;}=18;public string? HsnSacCode{get;set;}}
 public sealed class PlanInput{[Required]public Guid? FeeStructureId{get;set;}[Required]public string Name{get;set;}="Standard installments";[Range(1,24)]public int Count{get;set;}=4;public DateOnly FirstDueDate{get;set;}=DateOnly.FromDateTime(DateTime.UtcNow.AddDays(30));}
 public sealed class LateInput{public Guid? BranchId{get;set;}public Guid? FeeStructureId{get;set;}[Required]public string Name{get;set;}="Standard late fee";public LateFeeMethod Method{get;set;}=LateFeeMethod.Fixed;[Range(0,100000)]public decimal Value{get;set;}[Range(0,365)]public int GraceDays{get;set;}=5;public decimal? MaximumAmount{get;set;}}
 public sealed class ConcessionRuleInput{public Guid? BranchId{get;set;}[Required]public string Name{get;set;}="";[Required]public string Code{get;set;}="";public DiscountType Type{get;set;}public decimal Value{get;set;}public decimal? MaximumAmount{get;set;}public bool RequiresApproval{get;set;}=true;public string ConditionsJson{get;set;}="{}";}
 public sealed record BalanceRow(Guid AccountId,string Code,string Name,AccountType Type,decimal Debit,decimal Credit,decimal Balance);
 public async Task OnGetAsync()=>await Load();
 public async Task<IActionResult> OnPostAccountAsync(){db.ChartOfAccounts.Add(new(){BranchId=Account.BranchId,Code=Account.Code.Trim(),Name=Account.Name.Trim(),Type=Account.Type});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostVoucherAsync(){if(!Voucher.DebitAccountId.HasValue||!Voucher.CreditAccountId.HasValue||Voucher.DebitAccountId==Voucher.CreditAccountId){ModelState.AddModelError(string.Empty,"Choose two different accounts.");await Load();return Page();}var uid=Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier),out var u)?u:(Guid?)null;await finance.PostJournalAsync(new(){BranchId=Voucher.BranchId,JournalNumber=$"JV-{DateTime.UtcNow:yyyyMMddHHmmssfff}",PostingDate=Voucher.PostingDate,VoucherType=Voucher.Type,Narration=Voucher.Narration,PostedByUserId=uid,Lines=[new(){ChartOfAccountId=Voucher.DebitAccountId.Value,Debit=Voucher.Amount},new(){ChartOfAccountId=Voucher.CreditAccountId.Value,Credit=Voucher.Amount}]});Feedback="Balanced voucher posted.";return RedirectToPage();}
 public async Task<IActionResult> OnPostPeriodAsync(){db.AccountingPeriods.Add(new(){BranchId=Period.BranchId,Name=Period.Name,StartsOn=Period.StartsOn,EndsOn=Period.EndsOn});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostClosePeriodAsync(Guid id){var p=await db.AccountingPeriods.FindAsync(id);if(p is null)return NotFound();p.Status=AccountingPeriodStatus.Closed;p.ClosedOn=DateTime.UtcNow;p.ClosedByUserId=Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier),out var u)?u:null;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostBankAsync(){db.BankAccounts.Add(new(){BranchId=Bank.BranchId!.Value,ChartOfAccountId=Bank.ChartOfAccountId!.Value,BankName=Bank.BankName,AccountNumberMasked=Bank.AccountNumberMasked,IfscCode=Bank.IfscCode});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostStatementAsync(){db.BankStatementLines.Add(new(){BankAccountId=Statement.BankAccountId!.Value,TransactionDate=Statement.TransactionDate,Description=Statement.Description,Reference=Statement.Reference,Debit=Statement.Debit,Credit=Statement.Credit});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostMatchAsync(Guid id,Guid journalLineId){var line=await db.BankStatementLines.FindAsync(id);var jl=await db.JournalLines.FindAsync(journalLineId);if(line is null||jl is null)return NotFound();if(Math.Abs((line.Credit-line.Debit)-(jl.Debit-jl.Credit))>.01m){Feedback="Amounts do not reconcile.";return RedirectToPage();}line.Status=BankStatementStatus.Matched;line.MatchedJournalLineId=jl.Id;line.MatchedOn=DateTime.UtcNow;await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostTaxAsync(){db.TaxCodes.Add(new(){Code=Tax.Code,Name=Tax.Name,Type=Tax.Type,Rate=Tax.Rate,HsnSacCode=Tax.HsnSacCode});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostPlanAsync(){var structure=await db.FeeStructures.Include(x=>x.Components).SingleAsync(x=>x.Id==Plan.FeeStructureId);var total=structure.Components.Where(x=>!x.IsOptional).Sum(x=>x.Amount);var plan=new FeeInstallmentPlan{FeeStructureId=structure.Id,Name=Plan.Name};for(var i=1;i<=Plan.Count;i++)plan.Installments.Add(new(){Name=$"Installment {i}",Sequence=i,DueDate=Plan.FirstDueDate.AddMonths(i-1),Amount=Math.Round(total/Plan.Count,2),Percentage=Math.Round(100m/Plan.Count,4)});db.Add(plan);await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostLateAsync(){db.LateFeeRules.Add(new(){BranchId=Late.BranchId,FeeStructureId=Late.FeeStructureId,Name=Late.Name,Method=Late.Method,Value=Late.Value,GraceDays=Late.GraceDays,MaximumAmount=Late.MaximumAmount});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnPostApplyLateAsync(){Feedback=$"Updated {await finance.ApplyLateFeesAsync(DateOnly.FromDateTime(DateTime.UtcNow))} overdue invoices.";return RedirectToPage();}
 public async Task<IActionResult> OnPostConcessionAsync(){db.ConcessionRules.Add(new(){BranchId=Concession.BranchId,Name=Concession.Name,Code=Concession.Code,Type=Concession.Type,Value=Concession.Value,MaximumAmount=Concession.MaximumAmount,RequiresApproval=Concession.RequiresApproval,ConditionsJson=Concession.ConditionsJson});await db.SaveChangesAsync();return RedirectToPage();}
 public async Task<IActionResult> OnGetExportAsync(string package="general"){await Load();var sb=new StringBuilder("Date,Journal,Voucher,Narration,AccountCode,Account,Debit,Credit\r\n");foreach(var j in Journals)foreach(var l in j.Lines)sb.AppendLine($"{j.PostingDate:yyyy-MM-dd},{Csv(j.JournalNumber)},{j.VoucherType},{Csv(j.Narration)},{Csv(l.ChartOfAccount?.Code)},{Csv(l.ChartOfAccount?.Name)},{l.Debit},{l.Credit}");return File(Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(sb.ToString())).ToArray(),"text/csv",$"{package}-ledger-{DateTime.UtcNow:yyyyMMdd}.csv");}
 private async Task Load(){Branches=await branchAccess.FilterBranchesAsync(User,await db.Branches.AsNoTracking().ToListAsync());var ids=Branches.Select(x=>x.Id).ToList();Accounts=await db.ChartOfAccounts.AsNoTracking().Where(x=>x.BranchId==null||ids.Contains(x.BranchId.Value)).OrderBy(x=>x.Code).ToListAsync();Periods=await db.AccountingPeriods.AsNoTracking().Where(x=>x.BranchId==null||ids.Contains(x.BranchId.Value)).OrderByDescending(x=>x.StartsOn).ToListAsync();Journals=await db.JournalEntries.AsNoTracking().Include(x=>x.Lines).ThenInclude(x=>x.ChartOfAccount).Where(x=>x.BranchId==null||ids.Contains(x.BranchId.Value)).OrderByDescending(x=>x.PostingDate).Take(200).ToListAsync();Banks=await db.BankAccounts.AsNoTracking().Where(x=>ids.Contains(x.BranchId)).ToListAsync();var bankIds=Banks.Select(x=>x.Id).ToList();BankLines=await db.BankStatementLines.AsNoTracking().Where(x=>bankIds.Contains(x.BankAccountId)).OrderByDescending(x=>x.TransactionDate).Take(100).ToListAsync();Taxes=await db.TaxCodes.AsNoTracking().ToListAsync();Structures=await db.FeeStructures.AsNoTracking().Where(x=>ids.Contains(x.BranchId)).ToListAsync();var structureIds=Structures.Select(x=>x.Id).ToList();Plans=await db.FeeInstallmentPlans.AsNoTracking().Include(x=>x.Installments).Where(x=>structureIds.Contains(x.FeeStructureId)).ToListAsync();LateRules=await db.LateFeeRules.AsNoTracking().Where(x=>x.BranchId==null||ids.Contains(x.BranchId.Value)).ToListAsync();ConcessionRules=await db.ConcessionRules.AsNoTracking().Where(x=>x.BranchId==null||ids.Contains(x.BranchId.Value)).ToListAsync();TrialBalance=Journals.Where(x=>x.Status==JournalStatus.Posted).SelectMany(x=>x.Lines).GroupBy(x=>x.ChartOfAccount!).Select(g=>new BalanceRow(g.Key.Id,g.Key.Code,g.Key.Name,g.Key.Type,g.Sum(x=>x.Debit),g.Sum(x=>x.Credit),g.Sum(x=>x.Debit-x.Credit))).OrderBy(x=>x.Code).ToList();}
 private static string Csv(string? v)=>$"\"{(v??"").Replace("\"","\"\"")}\"";
}
